def stamp():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def sha256(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for b in iter(lambda: f.read(8 * 1024 * 1024), b''):
            h.update(b)
    return h.hexdigest()


def atomic_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + '.partial')
    temp.write_text(json.dumps(value, indent=2, sort_keys=True) + '\n')
    temp.replace(path)


def contained(path, parent):
    try:
        Path(path).resolve().relative_to(Path(parent).resolve())
        return True
    except ValueError:
        return False


def read_manifest(path):
    path = Path(path).resolve()
    value = json.loads(path.read_text())
    if value.get('schema') != 'gingival-portable-inputs-v1':
        raise RuntimeError('Unsupported input manifest schema')
    if value.get('package_spec_sha256') != SPEC['spec_sha256']:
        raise RuntimeError('Input manifest does not belong to this code version')
    entries = value['inputs']
    if len({x['role'] for x in entries}) != len(entries):
        raise RuntimeError('Duplicate input role in manifest')
    return path, entries


def select_stages(requested):
    by_id = {s['id']: dict(s) for s in SPEC['stages']}
    names = []
    for token in requested.split(','):
        if token == 'all':
            names.extend(s['id'] for s in SPEC['stages'] if s.get('default', True))
        elif token in {s.get('component') for s in SPEC['stages']}:
            names.extend(s['id'] for s in SPEC['stages'] if s.get('component') == token and s.get('default', True))
        else:
            names.append(token)
    chosen = set()
    def add(name):
        if name not in by_id:
            raise RuntimeError('Unknown stage: ' + name)
        if name in chosen:
            return
        chosen.add(name)
        for dep in by_id[name].get('depends_on', []):
            add(dep)
    for name in names:
        add(name)
    # Explicit raw core preprocessing must precede its matrix consumers.
    # Default processed-input reproduction does not acquire raw files.
    raw = 'core.raw_preprocessing'
    if raw in chosen:
        bound = set(by_id[raw].get('bind_outputs', {}))
        hashes = {row.get('sha256') for row in SPEC['inputs'] if row['role'] in bound}
        consumers = {'core.rna_preprocess'}
        for row in SPEC['inputs']:
            if row['role'] in bound or (row.get('sha256') and row['sha256'] in hashes):
                consumers.update(sid for sid in row.get('stages', [])
                                 if sid.startswith(('core.', 'core_extended.')))
        for sid in consumers & chosen:
            if sid not in {raw, 'core.raw_acquisition'}:
                by_id[sid]['depends_on'] = sorted(set(by_id[sid].get('depends_on', [])) | {raw})
    ordered, unresolved = [], set(chosen)
    while unresolved:
        ready = [by_id[s['id']] for s in SPEC['stages'] if s['id'] in unresolved and
                 not (set(by_id[s['id']].get('depends_on', [])) & unresolved)]
        if not ready:
            raise RuntimeError('Cyclic stage dependencies')
        ordered.extend(ready)
        unresolved.difference_update(s['id'] for s in ready)
    return ordered


def input_roles(stages):
    ids = {s['id'] for s in stages}
    return {x['role'] for x in SPEC['inputs']
            if not x.get('dynamic') and (not x.get('stages') or bool(ids & set(x['stages'])))}


def resolve_inputs(manifest_path, entries, data_dir, roles):
    base = Path(data_dir).expanduser().resolve() if data_dir else manifest_path.parent
    declared = {x['role']: x for x in entries}
    expected = {x['role']: x for x in SPEC['inputs']}
    resolved = {}
    for role in sorted(roles):
        if role not in declared:
            raise RuntimeError('Required data role missing from manifest: ' + role)
        row, canonical = declared[role], expected[role]
        if row.get('sha256') != canonical['sha256'] or row.get('bytes') != canonical['bytes']:
            raise RuntimeError('Manifest changed frozen data identity for ' + role)
        p = Path(row['file']).expanduser()
        if not p.is_absolute():
            p = base / p
        p = p.resolve()
        if not p.is_file():
            raise RuntimeError('Missing input ' + role + ': ' + str(p))
        if p.stat().st_size != canonical['bytes']:
            raise RuntimeError('Input size differs: ' + role)
        resolved[role] = p
    return resolved


def verify_inputs(resolved, out):
    expected = {x['role']: x for x in SPEC['inputs']}
    cache_path = out / 'audit/input_hash_cache.json'
    cache = json.loads(cache_path.read_text()) if cache_path.exists() else {}
    receipt = {}
    verified_objects = {}
    for i, (role, p) in enumerate(resolved.items(), 1):
        st = p.stat()
        identity = [str(p), st.st_size, st.st_mtime_ns, st.st_ctime_ns]
        old = cache.get(role, {})
        # Cached hash is usable only for the same source identity, never for new data.
        object_key = tuple(identity)
        actual = verified_objects.get(object_key)
        if actual is None:
            actual = old.get('sha256') if old.get('identity') == identity else sha256(p)
            verified_objects[object_key] = actual
        if actual != expected[role]['sha256']:
            raise RuntimeError('SHA256 differs for ' + role)
        cache[role] = {'identity': identity, 'sha256': actual}
        receipt[role] = {'file': str(p), 'bytes': st.st_size, 'sha256': actual}
        atomic_json(cache_path, cache)
        print(f'Input {i}/{len(resolved)} verified: {role}', flush=True)
    atomic_json(out / 'audit/Input_Verification.json',
                {'status': 'PASS_INPUT_IDENTITIES', 'time': stamp(),
                 'scientific_fits': 0, 'inputs': receipt})
    return receipt


def extract_sources(runtime):
    payload = base64.b85decode(EMBEDDED_SOURCE_ZIP.encode('ascii'))
    if hashlib.sha256(payload).hexdigest() != SPEC['source_archive_sha256']:
        raise RuntimeError('Embedded code archive identity failed')
    with zipfile.ZipFile(io.BytesIO(payload)) as z:
        for info in z.infolist():
            dest = runtime / info.filename
            if not contained(dest, runtime) or info.is_dir():
                if info.is_dir():
                    continue
                raise RuntimeError('Unsafe embedded path')
            content = z.read(info)
            if hashlib.sha256(content).hexdigest() != SPEC['assets'][info.filename]['sha256']:
                raise RuntimeError('Embedded source differs: ' + info.filename)
            dest.parent.mkdir(parents=True, exist_ok=True)
            if dest.exists():
                if dest.read_bytes() != content:
                    raise RuntimeError('Runtime source modified: ' + info.filename)
            else:
                dest.write_bytes(content)
    atomic_json(runtime.parent / 'audit/Embedded_Code_Identities.json',
                {'time': stamp(), 'source_archive_sha256': SPEC['source_archive_sha256'],
                 'assets': SPEC['assets']})


def bind_runtime_inputs(runtime, resolved):
    by_role = {x['role']: x for x in SPEC['inputs']}
    assigned = {}
    for role, src in resolved.items():
        row = by_role[role]
        targets = list(row.get('targets', []))
        if row.get('target'):
            targets += [row['target']]
        for rel in set(targets):
            target = runtime / rel
            # Check lexical target parent before creating a symlink; source may be anywhere.
            if '..' in Path(rel).parts or Path(rel).is_absolute():
                raise RuntimeError('Unsafe data alias for ' + role)
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.is_symlink() or target.exists():
                if target.resolve() != src:
                    prior = assigned.get(rel) or SPEC['assets'].get(rel, {}).get('sha256')
                    if prior is None and target.is_file():
                        prior = sha256(target)
                    if prior != row['sha256']:
                        raise RuntimeError('Runtime data alias collision: ' + str(target))
            else:
                try:
                    target.symlink_to(src)
                except OSError as exc:
                    raise RuntimeError('Cannot create data link; enable symbolic links on this system: '
                                       + str(target)) from exc
            assigned[rel] = row['sha256']


def format_token(token, mapping):
    result = str(token)
    for key, value in mapping.items():
        result = result.replace('{' + key + '}', str(value))
    return result


def r_temporary_alias(out):
    target = out / 'temporary'
    target.mkdir(parents=True, exist_ok=True)
    if not any(c.isspace() for c in str(target)):
        return target
    parent = Path(tempfile.gettempdir())
    if any(c.isspace() for c in str(parent)):
        raise RuntimeError('R requires a whitespace-free temporary alias directory')
    key = hashlib.sha256(str(out).encode()).hexdigest()[:24]
    alias = parent / ('gingival-rtemp-' + key)
    if alias.is_symlink():
        if alias.resolve() != target.resolve():
            raise RuntimeError('R temporary alias belongs to another run')
    elif alias.exists():
        raise RuntimeError('R temporary alias path is occupied')
    else:
        alias.symlink_to(target, target_is_directory=True)
    # This is only a filesystem link: all R temporary bytes remain in --out.
    return alias


def runtime_env(out, runtime, bindings, r_library, extra_libraries=()):
    env = dict(os.environ)
    tmp = r_temporary_alias(out)
    cache = out / 'cache'
    for p in [tmp, cache, out / 'R_user', out / 'R_library']:
        p.mkdir(parents=True, exist_ok=True)
    env.update(PYTHONDONTWRITEBYTECODE='1', TMPDIR=str(tmp), TMP=str(tmp), TEMP=str(tmp),
               XDG_CACHE_HOME=str(cache), MPLCONFIGDIR=str(cache / 'matplotlib'),
               JOBLIB_TEMP_FOLDER=str(tmp), NUMBA_CACHE_DIR=str(cache / 'numba'),
               R_USER=str(out / 'R_user'), R_PROFILE_USER=os.devnull, R_ENVIRON_USER=os.devnull,
               OMP_NUM_THREADS='1', OPENBLAS_NUM_THREADS='1', MKL_NUM_THREADS='1',
               VECLIB_MAXIMUM_THREADS='1', NUMEXPR_NUM_THREADS='1',
               PORTABLE_RUNTIME=str(runtime), PORTABLE_BINDINGS=str(bindings),
               PORTABLE_RUN_ROOT=str(out), PORTABLE_R_LIBRARY=str(r_library or ''))
    libraries = ([r_library] if r_library else []) + list(extra_libraries)
    if libraries:
        search = os.pathsep.join(str(x) for x in libraries)
        env['R_LIBS_USER'] = search
        env['R_LIBS'] = search
    return env


def stage_r_runtime(stage, args, env):
    profile = stage.get('r_profile', 'primary')
    executable = args.rscript_profiles.get(profile, args.rscript)
    library = args.r_library_profiles.get(profile, args.r_library)
    result_env = dict(env)
    if profile in args.r_library_profiles:
        result_env['R_LIBS_USER'] = str(library)
        result_env['R_LIBS'] = str(library)
    if profile in args.r_home_profiles:
        result_env['R_HOME'] = str(args.r_home_profiles[profile])
        result_env['RHOME'] = str(args.r_home_profiles[profile])
    result_env['PORTABLE_RSCRIPT'] = str(executable)
    result_env['PORTABLE_R_LIBRARY'] = str(library or '')
    return executable, library, result_env


def probe_runtime(args, env, stages, out):
    python_groups, r_groups = {}, {}
    for stage in stages:
        profile = stage.get('python_profile', stage.get('component', 'default'))
        executable = args.python_profiles.get(profile, args.python)
        group = python_groups.setdefault(executable, {'profiles': set(), 'packages': set()})
        group['profiles'].add(profile)
        group['packages'].update(stage.get('dependencies', {}).get('Python', []))
        rexec, library, renv = stage_r_runtime(stage, args, env)
        key = (str(rexec), str(library or ''))
        rgroup = r_groups.setdefault(key, {'env': renv, 'packages': set(), 'required_versions': set(), 'profiles': set()})
        rgroup['packages'].update(stage.get('dependencies', {}).get('R', []))
        rgroup['profiles'].add(stage.get('r_profile', 'primary'))
        if stage.get('required_r_version'):
            rgroup['required_versions'].add(stage['required_r_version'])
    receipt = {'time': stamp(), 'platform': platform.platform(), 'orchestration_python': sys.version,
               'Python': {}, 'R': [], 'errors': []}
    for executable, group in python_groups.items():
        names = sorted(group['packages'])
        expr = ('import importlib.metadata as m,json,sys; names=' + repr(names) +
                '; v={}; missing=[]\nfor n in names:\n try: v[n]=m.version(n)\n'
                ' except m.PackageNotFoundError: missing.append(n)\n'
                'print(json.dumps({"python":sys.version,"versions":v,"missing":missing}))')
        run = subprocess.run([executable, '-c', expr], env=env, text=True, capture_output=True)
        if run.returncode:
            receipt['errors'].append('Python runtime probe failed: ' + executable + ': ' + run.stderr[-2000:])
            continue
        result = json.loads(run.stdout)
        result['profiles'] = sorted(group['profiles'])
        receipt['Python'][executable] = result
        if result['missing']:
            receipt['errors'].append('Missing Python packages in ' + executable + ': ' + ', '.join(result['missing']))
    for (executable, library), group in r_groups.items():
        if not group['packages']:
            continue
        names = ','.join(json.dumps(n) for n in sorted(group['packages']))
        expr = ('pk<-c(' + names + '); cat(as.character(getRversion()),"\\n"); '
                'for(p in pk){loc<-tryCatch(find.package(p,quiet=FALSE),error=function(e)stop("Missing R package: ",p));'
                'cat(p,as.character(packageVersion(p)),sep="\\t");cat("\\n")}')
        run = subprocess.run([executable, '--vanilla', '-e', expr], env=group['env'], text=True, capture_output=True)
        lines = run.stdout.splitlines()
        result = {'executable': executable, 'library': library, 'profiles': sorted(group['profiles']),
                  'packages': lines, 'scope': 'Installed metadata; actual producers test namespaces/ABI'}
        receipt['R'].append(result)
        if run.returncode:
            receipt['errors'].append('R runtime probe failed: ' + executable + ': ' + run.stderr[-4000:])
        elif group['required_versions'] and (not lines or lines[0].strip() not in group['required_versions']):
            receipt['errors'].append('R version differs for '+','.join(group['profiles'])+
                                     '; required '+','.join(sorted(group['required_versions'])))
    atomic_json(out / 'audit/Runtime_Identity.json', receipt)
    if receipt['errors']:
        raise RuntimeError('\n'.join(receipt['errors']))
    return receipt


def output_hashes(stage_dir):
    result = {}
    for p in sorted(stage_dir.rglob('*')):
        if not p.is_file() or p.is_symlink():
            continue
        if any(x in {'tmp', 'temporary', 'cache', 'R_user'} for x in p.relative_to(stage_dir).parts):
            continue
        result[p.relative_to(stage_dir).as_posix()] = sha256(p)
    return result


def saved_stage_valid(receipt_path, stage_dir, signature):
    if not receipt_path.is_file():
        return False
    receipt = json.loads(receipt_path.read_text())
    if receipt.get('signature') != signature or receipt.get('status') not in {'COMPUTED', 'COMPUTED_WITH_QUALIFICATION'}:
        return False
    hashes = receipt.get('outputs', {})
    if not hashes:
        return False
    return all((stage_dir / p).is_file() and sha256(stage_dir / p) == h for p, h in hashes.items())


def restore_producer_artifacts(stage_dir, out):
    """Restore authenticated, stage-local snapshots to their private workflow.

    A later audit may legitimately update a native workflow file. On resume,
    restore each completed stage in dependency order from immutable snapshots.
    Original supplied data and embedded source files are never destinations.
    """
    receipt_file = stage_dir / 'execution_receipt.json'
    if not receipt_file.is_file():
        return
    value = json.loads(receipt_file.read_text())
    artifacts = value.get('immutable_artifacts', [])
    if not artifacts:
        return
    workspace = Path(value['mutable_workflow_root']).resolve()
    if not contained(workspace, out / 'workflows'):
        raise RuntimeError('Producer workflow is outside this run')
    for item in artifacts:
        relative = Path(item['workspace_relative_path'])
        snapshot = Path(item['snapshot_relative_path'])
        if relative.is_absolute() or snapshot.is_absolute() or '..' in relative.parts or '..' in snapshot.parts:
            raise RuntimeError('Unsafe producer snapshot path')
        src, target = stage_dir / snapshot, workspace / relative
        if not contained(src, stage_dir) or not contained(target.parent, workspace) or target.is_symlink():
            raise RuntimeError('Producer snapshot destination is unsafe')
        if not src.is_file() or sha256(src) != item['sha256']:
            raise RuntimeError('Producer snapshot identity differs: ' + str(snapshot))
        if target.is_file() and sha256(target) == item['sha256']:
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        partial = target.with_name(target.name + '.restoring')
        if partial.exists():
            partial.unlink()
        if sys.platform == 'darwin':
            copy = subprocess.run(['/bin/cp', '-c', str(src), str(partial)], capture_output=True)
            if copy.returncode:
                shutil.copyfile(src, partial)
        else:
            shutil.copyfile(src, partial)
        if sha256(partial) != item['sha256']:
            partial.unlink()
            raise RuntimeError('Restored producer artifact differs')
        partial.replace(target)


def stage_runtime_identity(stage, args, out, env):
    probe = json.loads((out / 'audit/Runtime_Identity.json').read_text())
    profile = stage.get('python_profile', stage.get('component', 'default'))
    executable = args.python_profiles.get(profile, args.python)
    py = probe.get('Python', {}).get(str(executable), {})
    required = stage.get('dependencies', {}).get('Python', [])
    identity = {'platform': probe['platform'], 'python_executable': str(executable),
                'python_version': py.get('python'),
                'python_packages': {n:py.get('versions', {}).get(n) for n in required}}
    r_packages = stage.get('dependencies', {}).get('R', [])
    if r_packages:
        rexec, library, selected_env = stage_r_runtime(stage, args, env)
        found = next((x for x in probe['R'] if x['executable']==str(rexec) and x['library']==str(library or '')), None)
        if found is None:
            raise RuntimeError('Missing recorded stage R runtime identity')
        lines = found['packages']
        versions = dict(line.split('\t', 1) for line in lines[1:] if '\t' in line)
        identity['R'] = {'executable': str(rexec), 'library': str(library or ''),
                         'R_home': selected_env.get('R_HOME', ''),
                         'extra_libraries': [str(x) for x in args.r_extra_library],
                         'version': lines[0].strip(),
                         'packages': {n:versions.get(n) for n in r_packages}}
    return identity


def run_stage(stage, args, out, runtime, env, identities):
    sid = stage['id']
    directory = out / 'results' / sid
    receipt_path = out / 'audit/stages' / (sid + '.json')
    derived_path = out / 'derived_bindings.json'
    stage_roles = {row['role'] for row in SPEC['inputs']
                   if sid in row.get('stages', []) or (not row.get('stages') and not row.get('dynamic'))}
    own_roles = set(stage.get('bind_outputs', {}))
    own_hashes = {row.get('sha256') for row in SPEC['inputs'] if row['role'] in own_roles}
    own_roles.update(row['role'] for row in SPEC['inputs']
                     if row.get('sha256') and row['sha256'] in own_hashes)
    derived_identity = {}
    if derived_path.is_file():
        for role, path in json.loads(derived_path.read_text()).items():
            if role in stage_roles and role not in own_roles and (stage.get('derived_input_roles') is None or role in stage['derived_input_roles']):
                value = Path(path)
                if value.is_file():
                    derived_identity[role] = sha256(value)
                elif value.is_dir():
                    # A directory binding is scientific input too; include its
                    # current ordinary-file contents, never its folder name.
                    members = output_hashes(value)
                    if not members:
                        raise RuntimeError('Derived input directory has no data: ' + role)
                    derived_identity[role] = hashlib.sha256(
                        json.dumps(members, sort_keys=True).encode()).hexdigest()
                else:
                    raise RuntimeError('Derived input disappeared: ' + role)
    dependency_identity = {}
    for dependency in stage.get('depends_on', []):
        previous = out / 'audit/stages' / (dependency + '.json')
        if not previous.is_file():
            raise RuntimeError('Missing upstream checkpoint: ' + dependency)
        value = json.loads(previous.read_text())
        if value.get('status') not in {'COMPUTED', 'COMPUTED_WITH_QUALIFICATION'}:
            raise RuntimeError('Upstream stage did not complete: ' + dependency)
        dependency_identity[dependency] = {'signature': value['signature'], 'outputs': value['outputs']}
    runtime_identity = stage_runtime_identity(stage, args, out, env)
    signature_data = {'runtime_identity': runtime_identity, 'derived_input_sha256': derived_identity, 'upstream': dependency_identity,
                      'code_spec': SPEC['spec_sha256'], 'stage': stage,
                      'input_sha256': {k: v['sha256'] for k, v in identities.items() if k in stage_roles}}
    signature = hashlib.sha256(json.dumps(signature_data, sort_keys=True).encode()).hexdigest()
    if args.resume and saved_stage_valid(receipt_path, directory, signature):
        restore_producer_artifacts(directory, out)
        print('Verified checkpoint: ' + sid, flush=True)
        return json.loads(receipt_path.read_text())
    if directory.exists() and any(directory.iterdir()):
        if not args.rerun_failed:
            raise RuntimeError('Stage directory is nonempty without a valid checkpoint: ' + sid +
                               '; use a new --out or --rerun-failed to archive the failed attempt')
        archive = out / 'failed_attempts' / (sid + '-' + time.strftime('%Y%m%dT%H%M%S'))
        archive.parent.mkdir(parents=True, exist_ok=True)
        directory.rename(archive)
    directory.mkdir(parents=True, exist_ok=True)
    chosen_r, chosen_r_library, selected_r_env = stage_r_runtime(stage, args, env)
    mapping = {'python': args.python, 'rscript': chosen_r, 'runtime': runtime, 'out': directory,
               'run_root': out, 'bindings': out / 'input_bindings.json',
               'r_library': chosen_r_library or '', 'temporary': env['TMPDIR'], 'temp': env['TMPDIR']}
    profile = stage.get('python_profile', stage.get('component', 'default'))
    chosen_python = args.python_profiles.get(profile, args.python)
    mapping['python'] = chosen_python
    command = [format_token(x, mapping) for x in stage['command']]
    cwd = Path(format_token(stage.get('cwd', '{runtime}'), mapping))
    stage_env = dict(selected_r_env)
    stage_env.update(PORTABLE_OUTPUT=str(directory), PORTABLE_PYTHON=str(chosen_python),
                     JPR_PYTHON=str(chosen_python), PUBLICATION_PYTHON=str(chosen_python))
    derived = out / 'derived_bindings.json'
    if derived.is_file():
        stage_env['PORTABLE_DERIVED_BINDINGS'] = str(derived)
    for key, value in stage.get('env', {}).items():
        stage_env[key] = format_token(value, mapping)
    logfile = out / 'logs' / (sid + '.log')
    logfile.parent.mkdir(parents=True, exist_ok=True)
    receipt = {'stage': sid, 'status': 'RUNNING', 'started': stamp(), 'command': command,
               'cwd': str(cwd), 'signature': signature, 'runtime_identity': runtime_identity, 'outputs': {},
               'scope': stage.get('scope', 'fresh calculation from declared processed inputs')}
    atomic_json(receipt_path, receipt)
    print('Running: ' + sid, flush=True)
    with logfile.open('w') as log:
        p = subprocess.Popen(command, cwd=cwd, env=stage_env, stdout=log, stderr=subprocess.STDOUT,
                             start_new_session=(os.name == "posix"))
        receipt['pid'] = p.pid
        atomic_json(receipt_path, receipt)
        try:
            while p.poll() is None:
                time.sleep(1)
            exit_code = p.returncode
        except KeyboardInterrupt:
            if os.name == 'posix':
                os.killpg(p.pid, signal.SIGTERM)
            else:
                p.terminate()
            try:
                p.wait(timeout=20)
            except subprocess.TimeoutExpired:
                if os.name == 'posix':
                    os.killpg(p.pid, signal.SIGKILL)
                else:
                    p.kill()
                p.wait()
            receipt.update(status='INTERRUPTED', ended=stamp(), exit_code=p.returncode)
            atomic_json(receipt_path, receipt)
            raise
    receipt.update(ended=stamp(), exit_code=exit_code)
    allowed = stage.get('allowed_exit_codes', [0])
    missing = [x for x in stage.get('outputs', []) if not (directory / x).is_file()]
    qualification = None
    for check in stage.get('receipt_checks', []):
        cp = directory / check['file']
        if not cp.is_file():
            missing.append(check['file']); continue
        result = json.loads(cp.read_text())
        key = check.get('key', 'status')
        accepted = check['allowed']
        if result.get(key) not in accepted:
            missing.append(check['file'] + ':' + key)
    if exit_code not in allowed or missing:
        receipt.update(status='FAILED', missing_outputs=missing,
                       log=str(logfile), outputs=output_hashes(directory))
        atomic_json(receipt_path, receipt)
        tail = '\n'.join(logfile.read_text(errors='replace').splitlines()[-20:])
        raise RuntimeError(f'Stage {sid} failed (exit {exit_code}). Log: {logfile}\n{tail}')
    if exit_code != 0 or stage.get('qualification'):
        qualification = stage.get('qualification', f'Producer returned documented exit code {exit_code}')
    receipt.update(status='COMPUTED_WITH_QUALIFICATION' if qualification else 'COMPUTED',
                   qualification=qualification, outputs=output_hashes(directory), log=str(logfile))
    if not receipt['outputs']:
        receipt['status'] = 'FAILED_NO_OUTPUT'
        atomic_json(receipt_path, receipt)
        raise RuntimeError('Producer returned without any output: ' + sid)
    atomic_json(receipt_path, receipt)
    print(receipt['status'] + ': ' + sid, flush=True)
    return receipt


def unpack_data(archives, destination):
    destination = Path(destination).expanduser().resolve()
    destination.mkdir(parents=True, exist_ok=True)
    required = {(x['sha256'], x['bytes']) for x in SPEC['inputs'] if not x.get('dynamic')}
    files = sorted(Path(archives).glob('*.zip')) if Path(archives).is_dir() else [Path(archives)]
    if not files:
        raise RuntimeError('No data ZIP archives found')
    for path in files:
        with zipfile.ZipFile(path) as z:
            if 'ARCHIVE_CONTENTS.json' not in z.namelist():
                raise RuntimeError('Not a study data archive: ' + str(path))
            members = json.loads(z.read('ARCHIVE_CONTENTS.json'))
            for row in members:
                if (row['sha256'], row['bytes']) not in required:
                    raise RuntimeError('Unknown data identity in archive')
                name = row['file']
                target = destination / name
                if Path(name).is_absolute() or '..' in Path(name).parts or not contained(target, destination):
                    raise RuntimeError('Unsafe data archive member')
                info = z.getinfo(name)
                if info.file_size != row['bytes']:
                    raise RuntimeError('Archive data size differs')
                if target.exists():
                    if sha256(target) != row['sha256']:
                        raise RuntimeError('Existing extracted input differs: ' + str(target))
                    continue
                target.parent.mkdir(parents=True, exist_ok=True)
                partial = target.with_name(target.name + '.partial')
                h = hashlib.sha256()
                with z.open(info) as src, partial.open('wb') as dst:
                    for block in iter(lambda: src.read(8 * 1024 * 1024), b''):
                        h.update(block); dst.write(block)
                if h.hexdigest() != row['sha256']:
                    partial.unlink()
                    raise RuntimeError('Extracted data checksum differs')
                partial.replace(target)
        print('Verified and unpacked: ' + path.name, flush=True)


def discover_inputs(data_dir, stages):
    base = Path(data_dir).expanduser().resolve()
    roles = input_roles(stages)
    expected = {x['role']: x for x in SPEC['inputs'] if x['role'] in roles}
    sizes = {x['bytes'] for x in expected.values()}
    found = {}
    for p in base.rglob('*'):
        if not p.is_file() or p.stat().st_size not in sizes:
            continue
        h = sha256(p)
        if h in {x['sha256'] for x in expected.values()}:
            found.setdefault(h, p.resolve())
    missing = [role for role, row in expected.items() if row['sha256'] not in found]
    if missing:
        raise RuntimeError('Required input byte objects not found: ' + ', '.join(missing))
    return {role: found[row['sha256']] for role, row in expected.items()}


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('--inputs', type=Path, help='JSON manifest mapping scientific data roles to file paths')
    p.add_argument('--data-dir', type=Path, help='Base for relative paths, or data tree to match by SHA256 when --inputs is omitted')
    p.add_argument('--unpack-data', type=Path, help='Directory of study data ZIPs or one archive; extract and verify to --data-dir, then exit')
    p.add_argument('--out', type=Path, help='New output folder, outside every input folder')
    p.add_argument('--font-dir', type=Path, help='Optional user-supplied Arial fonts for native saved-figure rendering')
    p.add_argument('--stages', default='all', help='all or comma-separated stage IDs; dependencies added automatically')
    p.add_argument('--list-stages', action='store_true')
    p.add_argument('--check-inputs', action='store_true', help='Hash verification and dependency preflight only; no fits')
    p.add_argument('--extract-code', type=Path, help='Optional readable extraction of embedded sources; no fits')
    p.add_argument('--python', default=sys.executable, help='Python executable for numerical modules')
    p.add_argument('--python-profile', action='append', default=[], metavar='NAME=EXE', help='Python executable for a component requiring another recorded environment')
    p.add_argument('--rscript', default='Rscript', help='Main Rscript executable')
    p.add_argument('--rscript-profile', action='append', default=[], metavar='NAME=EXE', help='Rscript for a stage requiring another recorded R version')
    p.add_argument('--r-library-profile', action='append', default=[], metavar='NAME=DIR', help='Dedicated installed R library for that profile')
    p.add_argument('--r-home-profile', action='append', default=[], metavar='NAME=DIR', help='Optional R home for a relocated interpreter; normal installations do not need it')
    p.add_argument('--r-library', type=Path, help='Optional R library path; otherwise normal installed libraries')
    p.add_argument('--r-extra-library', type=Path, action='append', default=[], help='Additional installed R library; may be repeated')
    p.add_argument('--resume', action='store_true', help='Reuse only hash-verified completed checkpoints')
    p.add_argument('--rerun-failed', action='store_true', help='Archive an unsuccessful stage directory before a fresh attempt')
    a = p.parse_args()
    # Resolve interpreter paths before stage subprocesses change their CWD.
    def executable_path(value):
        return os.path.abspath(os.path.expanduser(value)) if '/' in value or '\\' in value else value
    a.python = executable_path(a.python)
    a.rscript = executable_path(a.rscript)
    a.python_profiles = {}
    for item in a.python_profile:
        if '=' not in item:
            p.error('--python-profile must be NAME=EXE')
        key, value = item.split('=', 1)
        if not key or not value:
            p.error('--python-profile must be NAME=EXE')
        a.python_profiles[key] = executable_path(value)
    a.rscript_profiles, a.r_library_profiles, a.r_home_profiles = {}, {}, {}
    for items, mapping, resolve in [(a.rscript_profile, a.rscript_profiles, False), (a.r_library_profile, a.r_library_profiles, True), (a.r_home_profile, a.r_home_profiles, True)]:
        for item in items:
            if '=' not in item:
                p.error('Runtime profile must be NAME=VALUE')
            key, value = item.split('=', 1)
            if not key or not value:
                p.error('Runtime profile must be NAME=VALUE')
            mapping[key] = Path(value).expanduser().resolve() if resolve else executable_path(value)
    if a.r_library:
        a.r_library = a.r_library.expanduser().resolve()
    a.r_extra_library = [x.expanduser().resolve() for x in a.r_extra_library]
    if a.unpack_data:
        if not a.data_dir:
            p.error('--unpack-data requires --data-dir as extraction destination')
        unpack_data(a.unpack_data, a.data_dir)
        return
    if a.list_stages:
        for s in SPEC['stages']:
            print(s['id'] + '\t' + s.get('description', '') + '\t' + s.get('scope', 'fresh analysis'))
        return
    if a.extract_code:
        target = a.extract_code.expanduser().resolve()
        if target.exists() and any(target.iterdir()):
            raise RuntimeError('--extract-code requires a new or empty folder')
        target.mkdir(parents=True, exist_ok=True)
        extract_sources(target)
        print('Readable embedded code extracted to ' + str(target))
        return
    if not a.out or not (a.inputs or a.data_dir):
        p.error('--out plus --inputs or --data-dir are required for execution')
    stages = select_stages(a.stages)
    if a.inputs:
        manifest_path, entries = read_manifest(a.inputs)
        resolved = resolve_inputs(manifest_path, entries, a.data_dir, input_roles(stages))
    else:
        resolved = discover_inputs(a.data_dir, stages)
    out = a.out.expanduser().resolve()
    for src in resolved.values():
        if contained(src, out) or contained(out, src.parent):
            raise RuntimeError('Output overlaps an input location: ' + str(src))
    if out.exists() and any(out.iterdir()) and not a.resume:
        raise RuntimeError('Output must be new/empty, or use --resume')
    out.mkdir(parents=True, exist_ok=True)
    owner = out / 'audit/Package_Identity.json'
    if owner.exists() and json.loads(owner.read_text())['spec_sha256'] != SPEC['spec_sha256']:
        raise RuntimeError('Output folder belongs to a different portable code version')
    atomic_json(owner, {'version': PACKAGE_VERSION, 'spec_sha256': SPEC['spec_sha256'], 'time': stamp()})
    identities = verify_inputs(resolved, out)
    bindings = out / 'input_bindings.json'
    atomic_json(bindings, {k: str(v) for k, v in resolved.items()})
    runtime = out / 'embedded_runtime'
    extract_sources(runtime)
    bind_runtime_inputs(runtime, resolved)
    env = runtime_env(out, runtime, bindings, a.r_library, a.r_extra_library)
    if a.font_dir:
        env['PORTABLE_FONT_DIR'] = str(a.font_dir.expanduser().resolve())
    if a.r_extra_library:
        env['PORTABLE_FIGURE_R_LIBRARIES'] = os.pathsep.join(str(x) for x in a.r_extra_library)
    env.update(PORTABLE_PYTHON=str(a.python), PORTABLE_RSCRIPT=str(a.rscript),
               JPR_PYTHON=str(a.python), PUBLICATION_PYTHON=str(a.python))
    probe_runtime(a, env, stages, out)
    if a.check_inputs:
        print('Preflight complete; no statistical analyses were executed.')
        return
    receipts = []
    for s in stages:
        receipt = run_stage(s, a, out, runtime, env, identities)
        receipts.append(receipt)
        if s.get('bind_outputs'):
            path = out / 'derived_bindings.json'
            derived = json.loads(path.read_text()) if path.is_file() else {}
            for role, relative in s['bind_outputs'].items():
                output = out / 'results' / s['id'] / relative
                if not output.exists():
                    raise RuntimeError('Missing derived upstream output: ' + str(output))
                derived[role] = str(output.resolve())
                match = next((x for x in SPEC['inputs'] if x['role'] == role), None)
                if match and match.get('sha256'):
                    for equivalent in SPEC['inputs']:
                        if equivalent.get('sha256') == match['sha256']:
                            derived[equivalent['role']] = str(output.resolve())
            atomic_json(path, derived)
    qualifications = {r['stage']: r['qualification'] for r in receipts if r.get('qualification')}
    atomic_json(out / 'audit/Run_Summary.json',
                {'status': 'COMPLETED_WITH_QUALIFICATIONS' if qualifications else 'COMPLETED',
                 'ended': stamp(), 'version': PACKAGE_VERSION, 'stages': [r['stage'] for r in receipts],
                 'qualifications': qualifications, 'input_sha256': {k:v['sha256'] for k,v in identities.items()},
                 'scope_limitations': SPEC.get('limitations', [])})
    print('All selected stages finished. Summary: ' + str(out / 'audit/Run_Summary.json'))


if __name__ == '__main__':
    try:
        main()
    except KeyboardInterrupt:
        print('Stopped safely; finished stage checkpoints remain saved.', file=sys.stderr)
        sys.exit(130)
    except Exception as exc:
        print('ERROR: ' + str(exc), file=sys.stderr)
        sys.exit(1)
